mapper.select:
select distinct a.task_id, a.task_name, a.task_type as cType, d.dict_note as plan_type, a.task_state as cState, e.dict_note as task_state, a.task_count, a.task_count-a.task_wait as cruise_data_state1, a.task_wait as cruise_data_state2, a.task_abnormal, a.execute_time, a.check_user, a.check_date, a.modify_state, a.task_wait,a.create_time, a.remark FROM u_patrol_result a JOIN t_dict_business d ON a.task_type = d.dict_code and d.col_name = 'plan_type' LEFT JOIN t_dict_business e ON a.task_state = e.dict_code and e.col_name='task_state' LEFT JOIN u_patrol_data_result f ON a.task_id = f.task_id
LEFT JOIN t_std_device j on f.device_id = j.device_id
LEFT JOIN t_cruise_point_instance m on m.instance_id = f.instance_id LEFT JOIN t_std_devicemete k on k.device_mete_id = m.device_mete_id where 1 = 1 and a.task_name like concat('%',#{taskName, jdbcType=VARCHAR},'%')
and a.task_type = #{cType, jdbcType=INTEGER}
and a.task_state = #{cState, jdbcType=INTEGER}
and a.execute_time BETWEEN #{startDate, jdbcType=TIMESTAMP} AND #{endDate, jdbcType=TIMESTAMP}
and f.device_id IN
#{deviceIds,jdbcType=BIGINT}
and j.device_type = #{deviceType, jdbcType=INTEGER}
and k.mete_type = #{meteType, jdbcType=VARCHAR}
and m.custom_id = #{customId, jdbcType=VARCHAR} and a.check_user is null and a.check_user is not null
and a.task_state != 239 and a.task_state != 241 GROUP BY task_id order by a.execute_time desc

SELECT DISTINCT f.real_code, b.device_name, b.instance_name, b.cruise_type, h.dict_note as cruise_type_name, b.result_num, b.cruise_result, j.dict_note as cruise_result_name, b.cruise_time, b.cruise_abnormal, p.dict_note as abnormal_type1, IF(ISNULL(b.remark),p.dict_note,CONCAT(p.dict_note,',',x.dict_note)) as abnormal_type, b.remark, x.dict_note as abnormal_type2, b.evaluation_state, i.dict_note as evaluation_state_name, b.check_user, b.check_date, b.picpath as pic_path, b.identify_result, w.dict_note as identify_result_name, b.identify_state, b.person_check, b.device_id, q.device_point_id, b.instance_id, e.device_mete_id, q.state_zero, q.state_one, q.high_limit1, q.high_limit2, q.high_limit3, q.high_limit4, q.low_limit1, q.low_limit2, q.low_limit3, q.low_limit4, q.unit, q.mete_kind, q.meter_type, q.mete_type, m.dict_note as mete_kind_name, e.cruise_id as preset_id, k.camera_id, -- b.end_time, b.is_warn, q.alarm_state, q.alarm_level, s.dict_note as alarm_level_name, n.device_type, b.voice_path, conf.db_value as dbValue, conf.f_value as fValue FROM u_patrol_result a LEFT JOIN u_patrol_data_result b on a.task_id = b.task_id LEFT JOIN t_cruise_point_instance e on b.instance_id = e.instance_id LEFT JOIN t_std_device n on n.device_id = b.device_id LEFT JOIN t_std_device_attr f on f.device_id = b.device_id LEFT JOIN t_dict_business h on h.dict_code = b.cruise_type and h.col_name = 'cruise_type' LEFT JOIN t_dict_business i on i.dict_code = b.evaluation_state and i.col_name = 'evaluation_state' LEFT JOIN t_dict_business j on j.dict_code = b.cruise_result and j.col_name = 'cruise_result' LEFT JOIN t_dict_business p ON p.dict_code = b.cruise_abnormal and p.col_name = 'abnormal_type' LEFT JOIN t_std_devicemete q on q.device_mete_id = e.device_mete_id LEFT JOIN t_dict_business m on q.mete_kind = m.dict_code and m.col_name ='mete_kind' LEFT JOIN t_camera_preset k on k.preset_id = e.cruise_id LEFT JOIN t_dict_business w on w.dict_code = b.identify_result and w.col_name ='identify_result' LEFT JOIN t_dict_business s on s.dict_code = q.alarm_level and s.col_name ='alarm_level' LEFT JOIN t_dict_business x ON x.dict_code = b.remark and x.col_name = 'abnormal_type' left join t_voice_device voice on e.cruise_id = voice.voice_device_id left join t_voice_config conf on voice.config_id = conf.config_id WHERE 1 = 1 and b.task_id = #{taskId,jdbcType=VARCHAR}
and n.device_type = #{deviceType, jdbcType=INTEGER}
and b.cruise_type = #{cruiseType, jdbcType=INTEGER}
and cruise_time BETWEEN #{startTime, jdbcType=TIMESTAMP} AND #{endTime, jdbcType=TIMESTAMP}
and b.cruise_result = #{cruiseResult, jdbcType=INTEGER}
and e.custom_id = #{customId, jdbcType=VARCHAR}
and b.device_id IN
#{deviceIds,jdbcType=BIGINT}
ORDER BY b.cruise_time desc, b.instance_id asc, b.device_id asc, n.custom_id asc

SELECT DISTINCT f.real_code, b.device_name, b.instance_name, b.cruise_type, h.dict_note as cruise_type_name, b.result_num, b.cruise_result, j.dict_note as cruise_result_name, b.cruise_time, b.cruise_abnormal, p.dict_note as abnormal_type1, IF(ISNULL(b.remark),p.dict_note,CONCAT(p.dict_note,',',x.dict_note)) as abnormal_type, b.remark, x.dict_note as abnormal_type2, b.evaluation_state, i.dict_note as evaluation_state_name, b.check_user, b.check_date, b.picpath as pic_path, b.identify_result, w.dict_note as identify_result_name, b.identify_state, b.person_check, b.device_id, q.device_point_id, b.instance_id, e.device_mete_id, q.state_zero, q.state_one, q.high_limit1, q.high_limit2, q.high_limit3, q.high_limit4, q.low_limit1, q.low_limit2, q.low_limit3, q.low_limit4, q.unit, q.mete_kind, q.meter_type, q.mete_type, m.dict_note as mete_kind_name, e.cruise_id as preset_id, k.camera_id, -- b.end_time, b.is_warn, q.alarm_state, q.alarm_level, s.dict_note as alarm_level_name, n.device_type, b.voice_path FROM t_cruise_result a LEFT JOIN u_patrol_data_result b on a.task_id = b.task_id LEFT JOIN t_cruise_point_instance e on b.instance_id = e.instance_id LEFT JOIN t_std_device n on n.device_id = b.device_id LEFT JOIN t_std_device_attr f on f.device_id = b.device_id LEFT JOIN t_dict_business h on h.dict_code = b.cruise_type and h.col_name = 'cruise_type' LEFT JOIN t_dict_business i on i.dict_code = b.evaluation_state and i.col_name = 'evaluation_state' LEFT JOIN t_dict_business j on j.dict_code = b.cruise_result and j.col_name = 'cruise_result' LEFT JOIN t_dict_business p ON p.dict_code = b.cruise_abnormal and p.col_name = 'abnormal_type' LEFT JOIN t_std_devicemete q on q.device_mete_id = e.device_mete_id LEFT JOIN t_dict_business m on q.mete_kind = m.dict_code and m.col_name ='mete_kind' LEFT JOIN t_camera_preset k on k.preset_id = e.cruise_id LEFT JOIN t_dict_business w on w.dict_code = b.identify_result and w.col_name ='identify_result' LEFT JOIN t_dict_business s on s.dict_code = q.alarm_level and s.col_name ='alarm_level' LEFT JOIN t_dict_business x ON x.dict_code = b.remark and x.col_name = 'abnormal_type' WHERE 1 = 1 and b.task_result_id = #{taskResultId,jdbcType=VARCHAR}
and n.device_type = #{deviceType, jdbcType=INTEGER}
and g.cruise_type = #{cruiseType, jdbcType=INTEGER}
and cruise_time BETWEEN #{startTime, jdbcType=TIMESTAMP} AND #{endTime, jdbcType=TIMESTAMP}
and g.cruise_result = #{cruiseResult, jdbcType=INTEGER}
and e.custom_id = #{customId, jdbcType=VARCHAR}
and b.instance_name like concat('%',#{instanceName, jdbcType=VARCHAR},'%')
and b.device_id IN
#{deviceIds,jdbcType=BIGINT}
ORDER BY b.cruise_time DESC
